$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$entry = Decode ""
$page = Decode ""

$marketDetail = Join-Path $root "app\assistant\market\[id]\page.tsx"
$entryPath = Join-Path $root "app\assistant\market\[id]\SplitPlanEntryCard.tsx"
$reviewDir = Join-Path $root "app\assistant\market\[id]\split-plan"
$reviewPath = Join-Path $reviewDir "page.tsx"
$slotMapPath = Join-Path $root "app\api\market\requests\[id]\split-fallback\slot-map\route.ts"
$fallbackPath = Join-Path $root "app\api\market\requests\[id]\split-fallback\route.ts"

foreach ($path in @($marketDetail, $slotMapPath, $fallbackPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.17 : fichier requis introuvable : $path"
    }
}

$detail = [System.IO.File]::ReadAllText($marketDetail)
$slotMap = [System.IO.File]::ReadAllText($slotMapPath)
$fallback = [System.IO.File]::ReadAllText($fallbackPath)

if (-not $slotMap.Contains("KLYX_MULTI_PROVIDER_EXACT_SLOT_MAP_13_16")) {
    throw "13.17 : KLYX 13.16 introuvable."
}

if (-not $fallback.Contains("KLYX_MULTI_PROVIDER_FALLBACK_FIX_13_15B")) {
    throw "13.17 : KLYX 13.15b introuvable."
}

if ($detail.Contains("KLYX_MULTI_PROVIDER_REVIEW_WIRING_13_17")) {
    Write-Host "KLYX 13.17 deja applique."
    exit 0
}

$firstImport = $detail.IndexOf("import ")

if ($firstImport -lt 0) {
    throw "13.17 : imports de la page market introuvables."
}

$lastMainClose = $detail.LastIndexOf("</main>")

if ($lastMainClose -lt 0) {
    throw "13.17 : fermeture </main> introuvable."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $marketDetail -Destination ($marketDetail + ".bak-13-17-" + $timestamp) -Force

if (Test-Path -LiteralPath $entryPath) {
    Copy-Item -LiteralPath $entryPath -Destination ($entryPath + ".bak-13-17-" + $timestamp) -Force
}

if (Test-Path -LiteralPath $reviewPath) {
    Copy-Item -LiteralPath $reviewPath -Destination ($reviewPath + ".bak-13-17-" + $timestamp) -Force
}

$import = 'import SplitPlanEntryCard from "./SplitPlanEntryCard";' + "`r`n"

$detail = $detail.Insert($firstImport, $import)

# Recalcule apres insertion de l import.
$lastMainClose = $detail.LastIndexOf("</main>")

$render =
    "      {/* KLYX_MULTI_PROVIDER_REVIEW_WIRING_13_17 */}`r`n" +
    "      <SplitPlanEntryCard />`r`n`r`n"

$detail = $detail.Insert($lastMainClose, $render)

New-Item -ItemType Directory -Force -Path $reviewDir | Out-Null

[System.IO.File]::WriteAllText($entryPath, $entry, $utf8)
[System.IO.File]::WriteAllText($reviewPath, $page, $utf8)
[System.IO.File]::WriteAllText($marketDetail, $detail, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.17 APPLIQUE"
Write-Host "======================================"
Write-Host "Market detail : CONNECTE AU SPLIT PLAN"
Write-Host "Plan multi-provider : VISIBLE"
Write-Host "Prestataire par slot : VISIBLE"
Write-Host "Budgets par slot : VISIBLES"
Write-Host "Revalidation live : MANUELLE"
Write-Host "Selection automatique : NON"
Write-Host "Booking automatique : NON"
Write-Host "Paiement automatique : NON"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
